<!-- This file is generated by AI. -->

<!--
  应用外壳: 主题、应用级单例的启动、窗口形态与关闭确认。

  **全局样式与所有应用级事件接线都只在这里** —— 布局在应用生命周期内只挂载一次, 放进页面
  就会随页面重写而静默丢失 (最典型的是漏掉 `styles.css` 的 import: 界面变成没有样式的裸
  HTML, 而构建与类型检查仍然全绿)。

  启动顺序: 挂窗口保险丝 → 模块作用域写主题 (要早于首帧) → `onMount` 装配 Monaco 并拉起会话跟踪 →
  命令行指定的项目 (若有) → 语言服务与配音服务并行发起但不等待 →
  首帧绘制后由 `+page.svelte` 调 `revealWindow()` 显示窗口。

  项目级逻辑不在这里: 打开项目后才有意义的启动项在 `+page.svelte` 的编辑页分支里。
-->

<script lang="ts">
  import { getCurrentWindow } from '@tauri-apps/api/window';
  import type { Snippet } from 'svelte';
  import { onMount } from 'svelte';
  import { MediaQuery } from 'svelte/reactivity';

  import { openDevtools } from '../commands/devtools';
  import { startExternalDropWatcher } from '../dnd/external-drop.svelte';
  import { armWindowRevealFailsafe } from '../lib/boot';
  import { applyTheme, resolveTheme } from '../lib/theme';
  import { lspClient } from '../lsp/client';
  import { setMonacoTheme, setupMonaco } from '../lsp/monaco';
  import { openStartupProject, startSessionTracking } from '../project';
  import { actions, appStore } from '../state/store.svelte';
  import { requestClose, windowCloseAllowed } from '../unsaved';
  import AppConfirmDialog from '../ui/AppConfirmDialog.svelte';
  import PathDragGhost from '../ui/PathDragGhost.svelte';
  import TitleBar from '../ui/TitleBar.svelte';
  import UnsavedDialog from '../ui/UnsavedDialog.svelte';
  import { voiceController } from '../voice/controller';

  /*
   * 全局样式。必须在**布局**里引入: 它是整份应用的样式来源 (标题栏、开始界面、模态框、
   * 编辑器布局、Monaco 的配色钩子…), 放在页面里会随页面重写而被漏掉。
   */
  import '../styles.css';

  let { children }: { children?: Snippet } = $props();

  // 保险丝: 必须挂在任何可能抛错的初始化**之前** —— 主窗口是隐藏创建的, 挂载过程中任何一步抛错
  // 都会让 `+page.svelte` 的 `revealWindow()` 轮不到执行, 变成"启动了但看不到窗口, 也没报错"。
  armWindowRevealFailsafe();

  // 主题先落地, 要早于首帧: 只靠 `$effect` 会先看到一帧浅色再跳成深色。
  applyTheme(resolveTheme(appStore.settings.theme));

  /*
   * 主题的唯一权威链路。三件事必须由同一处同时完成, 否则就会各说各话:
   * `data-theme` 决定 `styles.css` 的变量、`store.theme` 决定标题栏显示哪个主题图标
   * (浅色 / 深色 / 跟随系统三态)、`setMonacoTheme()` 决定编辑器配色 (Monaco 自己一套主题)。
   */
  const systemDark = new MediaQuery('(prefers-color-scheme: dark)');
  const resolvedTheme = $derived(
    appStore.settings.theme === 'system' ? (systemDark.current ? 'dark' : 'light') : appStore.settings.theme
  );

  /**
   * 上一次真正落地过的主题。
   *
   * 刻意用**普通变量**而不是 `$state`: 它不该成为响应式依赖。
   *
   * 守卫是必需的: `updateSettings()` 每次都把 `appStore.settings` 换成新对象, 于是"读
   * `settings.theme`"的 effect 会在任何一次设置改动后重跑 —— 而它自己又会写 store, 两者
   * 叠加直接触发 `effect_update_depth_exceeded`。
   */
  let appliedTheme: 'light' | 'dark' | null = null;

  /** 把主题一次性落到三个地方 (DOM / store / Monaco)。幂等, 因此可以重复调用。 */
  function applyThemeEverywhere(theme: 'light' | 'dark'): void {
    if (theme === appliedTheme) return;
    appliedTheme = theme;
    actions.setTheme(theme);
    applyTheme(theme);
    setMonacoTheme(theme === 'dark');
  }

  $effect(() => {
    applyThemeEverywhere(resolvedTheme);
  });

  onMount(() => {
    // Monaco 的注册是应用级一次性动作 (语言、全部 provider、两套主题)。
    setupMonaco();

    /*
     * 主题要在 Monaco 注册之后重新落地一次。`$effect` 与 `onMount` 的先后顺序没有保证:
     * effect 先跑时 `setMonacoTheme()` 会作用在还没定义的主题名上 (Monaco 退回默认浅色),
     * 而幂等守卫记下的却是"已经设过深色", 于是再也不会重试。清掉守卫重设, 两个顺序都安全。
     */
    appliedTheme = null;
    applyThemeEverywhere(resolvedTheme);

    // 语言服务与配音服务并行启动, 不阻塞界面。
    void lspClient.start();
    void voiceController.initialize();
    const stopSessionTracking = startSessionTracking();

    /*
     * 命令行参数指定的项目 (`webgal-ink <项目目录>`)。
     *
     * 位置只能在这里, 而且必须在 `setupMonaco()` 之后: 打开项目会建 Monaco model, 语言 id 是
     * 刚才那次注册提供的。`+page.svelte` 的 `onMount` 比这里**更早** (子组件先挂载), 放在那边
     * 就会抢在 Monaco 注册之前。
     */
    void openStartupProject();

    /*
     * 系统关闭按钮 (右上角的叉 / Alt+F4) 要先问未保存的更改。
     *
     * `windowCloseAllowed()` 由 `requestClose` 在用户确认后置位 —— 那次调用会自己关窗,
     * 这里再收到事件时直接放行, 不会二次询问。
     */
    const win = getCurrentWindow();
    const unlisten = win.onCloseRequested((event) => {
      if (windowCloseAllowed()) return;
      if (!appStore.documents.some((doc) => doc.dirty)) return; // 没有未保存内容, 允许默认关闭
      event.preventDefault();
      requestClose();
    });

    /*
     * F12 打开开发者工具 (**只有调试构建**)。
     *
     * 后端的 `service/browser.rs` 把 WebView 自带的浏览器加速键整体关掉了 (Windows 上是
     * WebView2 的 `browser_accelerator_keys(false)`, 含它自带的 F12), 因此 WebView2 不会
     * 自己响应 F12 —— 必须由页面监听并调后端命令。发布构建不注册: 那时后端本就关闭了
     * 开发者工具, 命令本身也是空操作。
     */
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== 'F12') return;
      event.preventDefault();
      void openDevtools();
    };
    if (import.meta.env.DEV) window.addEventListener('keydown', onKeyDown);

    /*
     * 禁止把文件 / 链接拖进窗口, 否则 WebView 会直接**导航**到被拖入的内容, 编辑器连同未保存
     * 的改动一起消失。
     *
     * ⚠️ 系统文件拖放的**导入**不走这里: Tauri 接管拖放后页面根本收不到 `drop`
     * (见 `dnd/external-drop.svelte.ts`), 那条链路订阅的是 webview 的拖放事件。这里只是
     * 兜住"别让 WebView 跳走"。
     */
    const blockDrop = (event: DragEvent) => {
      if (event.defaultPrevented) return;
      event.preventDefault();
      if (event.dataTransfer) event.dataTransfer.dropEffect = 'none';
    };
    window.addEventListener('dragover', blockDrop);
    window.addEventListener('drop', blockDrop);

    /*
     * 系统文件拖进窗口: 落在场景 / 资源浏览器上 = 与「添加资源」同一套逻辑 (拷贝进来)。
     * 订阅是应用级的 (整个窗口一个), 落点由文件树自己登记。
     */
    let stopExternalDrop: (() => void) | null = null;
    void startExternalDropWatcher().then((stop) => {
      stopExternalDrop = stop;
    });

    /*
     * 吞掉 Monaco 在"编辑器销毁"时逃逸出来的 `Canceled` rejection。
     *
     * 来源是折叠控制器的 `updateScheduler`: 它在每次内容变化后 `trigger()`, 在 `dispose` 时
     * `cancel()`, 而那个 promise 没挂 `.catch`; 本应用每次切文档都会销毁并重建编辑器, 所以
     * 它很常见。折叠模型本来就是要被丢弃的, 这不是功能故障, 留在控制台只会淹没真正的错误。
     *
     * 只吞这一种: name 与 message 都是 `Canceled` 的 Error (本仓库自己的取消是
     * `voice/controller.ts` 那种 `isCanceled(taskId)` 布尔判据, 不产生它)。
     */
    const onUnhandledRejection = (event: PromiseRejectionEvent) => {
      const reason: unknown = event.reason;
      if (!(reason instanceof Error) || reason.name !== 'Canceled' || reason.message !== 'Canceled') return;
      event.preventDefault();
      if (import.meta.env.DEV) console.debug('[monaco] 忽略销毁编辑器时的 CancellationError');
    };
    window.addEventListener('unhandledrejection', onUnhandledRejection);

    return () => {
      window.removeEventListener('keydown', onKeyDown);
      window.removeEventListener('dragover', blockDrop);
      window.removeEventListener('drop', blockDrop);
      window.removeEventListener('unhandledrejection', onUnhandledRejection);
      stopExternalDrop?.();
      stopSessionTracking();
      void unlisten.then((off) => off());
    };
  });
</script>

<div class="app-root">
  <!-- 自绘标题栏: 开始界面与编辑界面共用 (原生标题栏已在 tauri.conf.json 关闭) -->
  <TitleBar />

  {@render children?.()}

  <!-- 未保存 / 通用确认对话框是应用级的, 开始界面与编辑页共用 -->
  <UnsavedDialog />
  <AppConfirmDialog />

  <!-- 拖拽路径时跟着指针的浮层 (见 `dnd/path-drag.svelte.ts`) -->
  <PathDragGhost />
</div>
